package cn.zhuatech.lms.controller; import cn.zhuatech.lms.common.ApiResponse; import cn.zhuatech.lms.dto.LmsDto.*; import cn.zhuatech.lms.service.LmsService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('LMS_MANAGER','QUALITY','ADMIN')") public class LearningAdminController {private final LmsService service;public LearningAdminController(LmsService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<LearningPlanView>> orders(){return ApiResponse.ok(service.learningPlans());}}
